[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [Parameter(Mandatory=$true)][string]$PrePilotAuditPath,
    [Parameter(Mandatory=$true)][string]$TelemetryResultPath,
    [string]$UnityPath='H:\UnityEditor\2022.3.30f1c1\Editor\Unity.exe',
    [switch]$BindingSmokeOnly
)

$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'Gate12R pilot requires an explicit absolute ProjectPath.'}
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate12RPilot|$ProjectPath");exit 0}
$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$PrePilotAuditPath=[IO.Path]::GetFullPath($PrePilotAuditPath);$TelemetryResultPath=[IO.Path]::GetFullPath($TelemetryResultPath);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate12RProcessReusePreparation.psm1') -Force
$plan=Read-Gate12RJson $PilotPlanPath;$provenance=Read-Gate12RJson $ProvenancePath;$audit=Read-Gate12RJson $PrePilotAuditPath
if($audit.passed-ne$true-or$audit.pilotExecutionAuthorizedByAudit-ne$true-or$audit.gate13rAuthorized-ne$false){throw 'Validation-only pre-pilot audit did not authorize this non-formal pilot.'}
if([string]$audit.pilotPlanSha256-ne(Get-Gate12RLowerSha256 $PilotPlanPath)-or[string]$audit.provenanceSha256-ne(Get-Gate12RLowerSha256 $ProvenancePath)-or[string]$audit.telemetryResultSha256-ne(Get-Gate12RLowerSha256 $TelemetryResultPath)){throw 'Pre-pilot audit is not byte-bound to the selected inputs.'}
$pilotRoot=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\')));$pilotBase=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\PilotRuns\Gate12R_ProcessReuse_5pct'))
if(-not$pilotRoot.StartsWith($pilotBase.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Pilot root is outside Gate12R versioned base.'}
$formalRoot=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')))
if(Test-Path -LiteralPath $pilotRoot){throw "Create-new pilot root already exists: $pilotRoot"};if(Test-Path -LiteralPath $formalRoot){throw 'Gate13R formal root must remain absent.'}
if((Get-Gate12RLowerSha256 $UnityPath)-ne[string]$plan.unity.executableSha256){throw 'Unity executable hash mismatch.'}
foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');if(-not(Test-Path $path)-or(Get-Gate12RLowerSha256 $path)-ne[string]$binding.sha256){throw "Provenance binding failed: $($binding.relativePath)"}}
$campaigns=@(Get-Gate12RCampaigns -ProjectPath $ProjectPath -Plan $plan);$schedule=@(Get-Gate12RMeasuredSchedule -Plan $plan -Campaigns $campaigns)
$runner=Join-Path $ProjectPath 'Research\Run-Gate12RProcessReuseBlockV4.ps1';$coldRunner=Join-Path $ProjectPath 'Research\Run-Gate12RColdReferenceV3.ps1';$analyzer=Join-Path $ProjectPath 'Research\Analyze-Gate12RPilot.ps1'
$windowsPowerShell='C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe';$nativeModulePath=@('C:\Users\bdscy\Documents\WindowsPowerShell\Modules','C:\Program Files\WindowsPowerShell\Modules','C:\WINDOWS\System32\WindowsPowerShell\v1.0\Modules')-join';'

if(-not('Gate12R.NativePower' -as[type])){Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace Gate12R {
 [StructLayout(LayoutKind.Sequential)] public struct SystemPowerStatus { public byte ACLineStatus; public byte BatteryFlag; public byte BatteryLifePercent; public byte Reserved1; public int BatteryLifeTime; public int BatteryFullLifeTime; }
 public static class NativePower { [DllImport("kernel32.dll", SetLastError=true)] public static extern bool GetSystemPowerStatus(out SystemPowerStatus status); }
}
'@}

function Get-EnvironmentSnapshot([string]$Phase){
    $processors=@(Get-CimInstance Win32_Processor);$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$loads=New-Object Collections.Generic.List[double]
    for($i=0;$i-lt[int]$plan.environment.cpuLoadSampleCount;$i++){$load=($processors|Measure-Object LoadPercentage -Average).Average;$loads.Add($(if($null-eq$load){0.0}else{[double]$load}));if($i-lt[int]$plan.environment.cpuLoadSampleCount-1){Start-Sleep -Seconds ([int]$plan.environment.cpuLoadSampleIntervalSeconds);$processors=@(Get-CimInstance Win32_Processor)}}
    $powerRaw=(&powercfg.exe /getactivescheme 2>&1|Out-String).Trim();$match=[regex]::Match($powerRaw,'(?i)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
    $powerStatus=New-Object Gate12R.SystemPowerStatus;$powerStatusOk=[Gate12R.NativePower]::GetSystemPowerStatus([ref]$powerStatus)
    $thermal=@();$thermalError=$null;try{$thermal=@(Get-CimInstance -Namespace root/wmi -ClassName MSAcpi_ThermalZoneTemperature -ErrorAction Stop|ForEach-Object {[math]::Round(([double]$_.CurrentTemperature/10.0)-273.15,2)})}catch{$thermalError=$_.Exception.Message}
    $drive=New-Object IO.DriveInfo ([IO.Path]::GetPathRoot($pilotRoot));$mean=[double](($loads.ToArray()|Measure-Object -Average).Average);$free=[long]([double]$os.FreePhysicalMemory*1KB);$failed=New-Object Collections.Generic.List[string]
    if(-not$match.Success-or$match.Value.ToLowerInvariant()-ne[string]$plan.environment.requiredPowerSchemeGuid){$failed.Add('power-scheme')};if(-not$powerStatusOk-or[int]$powerStatus.ACLineStatus-ne1){$failed.Add('ac-line')};if($free-lt[long]$plan.environment.minimumFreePhysicalMemoryBytes){$failed.Add('free-memory')};if($mean-gt[double]$plan.environment.maximumMeanCpuLoadPercent){$failed.Add('mean-cpu-load')};if($drive.AvailableFreeSpace-lt[long]$plan.environment.minimumPilotDriveFreeBytes){$failed.Add('pilot-storage')};if(@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-gt0){$failed.Add('unity-process')};if(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile')){$failed.Add('unity-lockfile')};if(Test-Path $formalRoot){$failed.Add('formal-root')}
    return [pscustomobject][ordered]@{schemaVersion=1;snapshotKind='gate12r-environment-power-thermal-storage-preflight-v1';phase=$Phase;capturedAtUtc=[DateTime]::UtcNow.ToString('o');machineName=$env:COMPUTERNAME;userName=$env:USERNAME;cpuModels=@($processors|ForEach-Object{([string]$_.Name).Trim()});logicalProcessorCount=[int]$cs.NumberOfLogicalProcessors;totalPhysicalMemoryBytes=[long]$cs.TotalPhysicalMemory;freePhysicalMemoryBytes=$free;operatingSystem=[string]$os.Caption;powerSchemeRaw=$powerRaw;powerSchemeGuid=if($match.Success){$match.Value.ToLowerInvariant()}else{$null};systemPowerStatusAvailable=$powerStatusOk;acLineStatus=if($powerStatusOk){[int]$powerStatus.ACLineStatus}else{$null};batteryFlag=if($powerStatusOk){[int]$powerStatus.BatteryFlag}else{$null};cpuLoadSamplesPercent=$loads.ToArray();meanCpuLoadPercent=$mean;thermalTemperaturesCelsius=$thermal;thermalStatus=if($thermal.Count){'available'}else{'unavailable-under-preregistered-policy'};thermalQueryError=$thermalError;temperatureUnavailablePolicy=[string]$plan.environment.temperatureUnavailablePolicy;outputDriveFreeBytes=[long]$drive.AvailableFreeSpace;unityProcessIds=@(Get-Process -Name Unity -ErrorAction SilentlyContinue|ForEach-Object Id);unityLockfilePresent=Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile');formalRootPresent=Test-Path $formalRoot;failedChecks=$failed.ToArray();passed=$failed.Count-eq0}
}
function Invoke-Child([string[]]$Arguments,[string]$Stdout,[string]$Stderr){$old=$env:PSModulePath;try{$env:PSModulePath=$nativeModulePath;&$windowsPowerShell @Arguments 1>$Stdout 2>$Stderr;return [int]$LASTEXITCODE}finally{$env:PSModulePath=$old}}
function Write-Checkpoint([string]$Status,[string]$ErrorMessage){$checkpoint=[ordered]@{schemaVersion=1;checkpointKind='gate12r-process-reuse-5pct-pilot-checkpoint-v1';status=$Status;savedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-Gate12RLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate12RLowerSha256 $ProvenancePath;prePilotAuditSha256=Get-Gate12RLowerSha256 $PrePilotAuditPath;completedEntryCount=$script:entries.Count;entries=$script:entries.ToArray();error=$ErrorMessage;formalCampaign=$false;excludedFromFormalAnalysis=$true;automaticResumeAuthorized=$false;gate13rAuthorized=$false};Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'pilot-checkpoint.json') -Value $checkpoint -Depth 40}
function Get-DirectoryRawBytes([string]$Path){return Get-Gate12RRawBytes $Path}
function Invoke-Block($Campaign,[int]$Block,[string]$Role,[string]$Prefix,[string]$RelativeOutput,[int]$Ordinal,[int]$Wave,[int]$WaveSlot){
    $blockPlan=New-Gate12RBlockPlan -ProjectPath $ProjectPath -Plan $plan -Provenance $provenance -Campaign $Campaign -Block $Block -ProvenancePath $ProvenancePath -TelemetryProbeResultPath $TelemetryResultPath -AnalysisRole $Role -CampaignIdPrefix $Prefix
    $safeName=('{0:D4}-{1}-b{2:D3}'-f$Ordinal,[string]$Campaign.campaignId,$Block);$planFile=Join-Path $pilotRoot ('plans\'+$Role+'\'+$safeName+'.block-plan.json');$planParent=Split-Path -Parent $planFile;if(-not(Test-Path $planParent)){New-Item -ItemType Directory -Path $planParent -Force|Out-Null};Write-Gate12RUtf8NoBomJson -Path $planFile -Value $blockPlan -Depth 30
    $output=Join-Path $pilotRoot $RelativeOutput;$outParent=Split-Path -Parent $output;if(-not(Test-Path $outParent)){New-Item -ItemType Directory -Path $outParent -Force|Out-Null};$stdout=$output+'.wrapper.stdout.log';$stderr=$output+'.wrapper.stderr.log'
    $args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$runner,'-ProjectPath',$ProjectPath,'-BlockPlanPath',$planFile,'-OutputDirectory',$output,'-AllowedRoot',$pilotRoot,'-Mode','Pilot','-UnityPath',$UnityPath)
    $started=Get-Date;Write-Host("[{0}/{1}] {2} {3} block {4}"-f$Ordinal,[int]$plan.totals.totalUnityProcesses,$Role,$Campaign.campaignId,$Block)-ForegroundColor Cyan;$exit=Invoke-Child $args $stdout $stderr;$completed=Get-Date;$summaryPath=$output+'.summary.json'
    if($exit-ne0-or-not(Test-Path $summaryPath)){throw "Block failed without resume/retry: $($blockPlan.blockId) exit=$exit stderr=$stderr"};$wrapper=Read-Gate12RJson $summaryPath;if($wrapper.passed-ne$true){throw "Block wrapper did not pass: $($blockPlan.blockId)"};$manifestPath=Join-Path $output 'block-manifest.json';$manifest=Read-Gate12RJson $manifestPath
    return [pscustomobject][ordered]@{role=$Role;ordinal=$Ordinal;wave=$Wave;waveSlot=$WaveSlot;campaignId=[string]$Campaign.campaignId;scenarioId=[string]$Campaign.scenarioId;comparisonCohortId=[string]$Campaign.comparisonCohortId;block=$Block;blockId=[string]$blockPlan.blockId;planRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $planFile;planSha256=Get-Gate12RLowerSha256 $planFile;outputRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $output;wrapperSummaryRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $summaryPath;wrapperSummarySha256=Get-Gate12RLowerSha256 $summaryPath;blockManifestSha256=Get-Gate12RLowerSha256 $manifestPath;processId=[int]$manifest.processId;sampleCount=[int]$manifest.completedSampleCount;wallSeconds=($completed-$started).TotalSeconds;rawBytes=Get-DirectoryRawBytes $output;formalCampaign=$false;completed=$true}
}
function Invoke-Cold($Campaign,[string]$Algorithm,[int]$Ordinal){
    $slug=Get-Gate12RAlgorithmSlug $Algorithm;$relative='cold-control\{0}\{1}'-f[string]$Campaign.campaignId,$slug;$output=Join-Path $pilotRoot $relative;$parent=Split-Path -Parent $output;if(-not(Test-Path $parent)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$scenario=Join-Path $ProjectPath ([string]$Campaign.scenarioRelativePath).Replace('/','\');$runId='g12r-cold-'+([string]$Campaign.campaignId).Replace('--','-')+'-'+$slug;$stdout=$output+'.wrapper.stdout.log';$stderr=$output+'.wrapper.stderr.log'
    $args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$coldRunner,'-ProjectPath',$ProjectPath,'-ScenarioPath',$scenario,'-OutputDirectory',$output,'-AllowedRoot',$pilotRoot,'-RunId',$runId,'-Algorithm',$Algorithm,'-UnityPath',$UnityPath)
    $started=Get-Date;Write-Host("[{0}/{1}] cold-control {2}/{3}"-f$Ordinal,[int]$plan.totals.totalUnityProcesses,$Campaign.campaignId,$Algorithm)-ForegroundColor DarkCyan;$exit=Invoke-Child $args $stdout $stderr;$completed=Get-Date;$summaryPath=$output+'.summary.json';if($exit-ne0-or-not(Test-Path $summaryPath)){throw "Cold control failed without retry: $runId exit=$exit stderr=$stderr"};$wrapper=Read-Gate12RJson $summaryPath;if($wrapper.passed-ne$true){throw "Cold wrapper did not pass: $runId"}
    return [pscustomobject][ordered]@{role='excluded-cold-structural-control';ordinal=$Ordinal;campaignId=[string]$Campaign.campaignId;scenarioId=[string]$Campaign.scenarioId;comparisonCohortId=[string]$Campaign.comparisonCohortId;algorithmId=$Algorithm;runId=$runId;outputRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $output;wrapperSummaryRelativePath=Get-Gate12RProjectRelativePath $ProjectPath $summaryPath;wrapperSummarySha256=Get-Gate12RLowerSha256 $summaryPath;manifestSha256=Get-Gate12RLowerSha256 (Join-Path $output 'manifest.json');workloadResultSha256=Get-Gate12RLowerSha256 (Join-Path $output 'workload-result.json');sampleCount=1;wallSeconds=($completed-$started).TotalSeconds;rawBytes=Get-DirectoryRawBytes $output;formalCampaign=$false;completed=$true}
}
function Write-PartialManifest([string]$Status){$files=@(Get-ChildItem -LiteralPath $pilotRoot -Recurse -File -Force|Where-Object {$_.Name-notlike'*.tmp-*'});$rows=New-Object Collections.Generic.List[object];foreach($file in $files){$rows.Add([pscustomobject]@{relativePath=Get-Gate12RProjectRelativePath $ProjectPath $file.FullName;rawBytes=[long]$file.Length;sha256=Get-Gate12RLowerSha256 $file.FullName})};$manifest=[ordered]@{schemaVersion=1;manifestKind='gate12r-pilot-partial-output-manifest-v1';status=$Status;savedAtUtc=[DateTime]::UtcNow.ToString('o');fileCount=$rows.Count;rawBytes=[long](($files|Measure-Object Length -Sum).Sum);files=$rows.ToArray();formalCampaign=$false;excludedFromFormalAnalysis=$true};Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'partial-output-manifest.json') -Value $manifest -Depth 20}

$startEnvironment=Get-EnvironmentSnapshot 'launch-preflight-before-pilot-root';if(-not$startEnvironment.passed){throw "Gate12R launch preflight failed before root creation: $($startEnvironment.failedChecks-join', ')"}
New-Item -ItemType Directory -Path $pilotRoot|Out-Null;New-Item -ItemType Directory -Path (Join-Path $pilotRoot 'plans')|Out-Null
$script:entries=New-Object Collections.Generic.List[object];$pilotStarted=Get-Date
try{
    Write-Gate12RUtf8NoBomJson -Path (Join-Path $pilotRoot 'environment-start.json') -Value $startEnvironment -Depth 20
    $receipt=[ordered]@{schemaVersion=1;receiptKind='gate12r-non-formal-pilot-execution-receipt-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');pilotRoot=$pilotRoot;pilotPlanSha256=Get-Gate12RLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate12RLowerSha256 $ProvenancePath;prePilotAuditSha256=Get-Gate12RLowerSha256 $PrePilotAuditPath;telemetryResultSha256=Get-Gate12RLowerSha256 $TelemetryResultPath;executionDesignId=[string]$plan.executionDesignId;nonFormal=$true;excludedFromFormalAnalysis=$true;automaticResumeAuthorized=$false;partialAttemptMergeAuthorized=$false;gate13rAuthorized=$false}
    Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'execution-receipt.json') -Value $receipt -Depth 20;Write-Checkpoint 'preflight-passed' $null
    $ordinal=1
    foreach($warm in @($plan.warmup.blocks)){$campaign=@($campaigns|Where-Object campaignId -eq ([string]$warm.campaignId))[0];$relative='warmup\{0:D2}-{1}\b{2:D3}'-f$ordinal,[string]$campaign.campaignId,[int]$warm.block;$script:entries.Add((Invoke-Block $campaign ([int]$warm.block) 'excluded-warmup' ('g12r-warm{0:D2}'-f$ordinal) $relative $ordinal 0 0));Write-Checkpoint 'running-warmup' $null;$ordinal++}
    Start-Sleep -Seconds ([int]$plan.warmup.quietStabilizationSeconds)
    $postWarmup=Get-EnvironmentSnapshot 'post-warmup-after-quiet-stabilization';Write-Gate12RUtf8NoBomJson -Path (Join-Path $pilotRoot 'environment-post-warmup.json') -Value $postWarmup -Depth 20;if(-not$postWarmup.passed){throw "Post-warmup preflight failed: $($postWarmup.failedChecks-join', ')"}
    foreach($campaign in $campaigns){foreach($algorithm in @($campaign.algorithms)){$script:entries.Add((Invoke-Cold $campaign $algorithm $ordinal));Write-Checkpoint 'running-cold-structural-controls' $null;$ordinal++}}
    $measuredOrdinal=0
    foreach($item in $schedule){$measuredOrdinal++;$campaign=$item.campaign;$relative='measured\{0:D2}-{1}\b{2:D3}'-f[int]$campaign.ordinal,[string]$campaign.campaignId,[int]$item.block;$script:entries.Add((Invoke-Block $campaign ([int]$item.block) 'measured-non-formal-pilot' ('g12r-measured-c{0:D2}'-f[int]$campaign.ordinal) $relative $ordinal ([int]$item.wave) ([int]$item.waveSlot)));Write-Checkpoint 'running-measured-blocks' $null;$ordinal++}
    $endEnvironment=Get-EnvironmentSnapshot 'end-after-measured-blocks';Write-Gate12RUtf8NoBomJson -Path (Join-Path $pilotRoot 'environment-end.json') -Value $endEnvironment -Depth 20
    $warmCount=@($script:entries|Where-Object role -eq 'excluded-warmup').Count;$coldCount=@($script:entries|Where-Object role -eq 'excluded-cold-structural-control').Count;$measuredCount=@($script:entries|Where-Object role -eq 'measured-non-formal-pilot').Count;$measuredSamples=[int](($script:entries|Where-Object role -eq 'measured-non-formal-pilot'|Measure-Object sampleCount -Sum).Sum)
    if($warmCount-ne8-or$coldCount-ne36-or$measuredCount-ne384-or$measuredSamples-ne1152-or$script:entries.Count-ne428){throw 'Pilot cardinality mismatch before analysis.'}
    $execution=[ordered]@{schemaVersion=1;manifestKind='gate12r-process-reuse-5pct-pilot-execution-manifest-v1';startedAtUtc=$pilotStarted.ToUniversalTime().ToString('o');completedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-Gate12RLowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate12RLowerSha256 $ProvenancePath;telemetryProbeProcessCount=1;warmupBlockProcessCount=$warmCount;warmupSampleCount=[int](($script:entries|Where-Object role -eq 'excluded-warmup'|Measure-Object sampleCount -Sum).Sum);coldControlProcessCount=$coldCount;coldControlSampleCount=$coldCount;measuredBlockProcessCount=$measuredCount;measuredSampleCount=$measuredSamples;totalUnityProcessCount=1+$script:entries.Count;totalSampleCount=[int](($script:entries|Measure-Object sampleCount -Sum).Sum);entries=$script:entries.ToArray();formalCampaign=$false;excludedFromFormalAnalysis=$true;automaticRetryCount=0;automaticResumeCount=0;gate13rAuthorized=$false;completed=$true}
    if([int]$execution.totalUnityProcessCount-ne429-or[int]$execution.totalSampleCount-ne1212){throw 'Frozen total process/sample cardinality mismatch.'}
    Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'pilot-execution-manifest.json') -Value $execution -Depth 40;Write-Checkpoint 'execution-complete-analysis-pending' $null
    $analysisStdout=Join-Path $pilotRoot 'analysis.stdout.log';$analysisStderr=Join-Path $pilotRoot 'analysis.stderr.log';$analysisArgs=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$analyzer,'-ProjectPath',$ProjectPath,'-PilotRoot',$pilotRoot,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath);$analysisExit=Invoke-Child $analysisArgs $analysisStdout $analysisStderr;if($analysisExit-ne0){throw "Pilot analysis failed without retry/resume: exit=$analysisExit stderr=$analysisStderr"}
    $pilotManifest=Read-Gate12RJson (Join-Path $pilotRoot 'pilot-manifest.json');if($pilotManifest.completed-ne$true-or$pilotManifest.gate13rAuthorized-ne$false){throw 'Pilot manifest did not complete under the non-formal boundary.'}
    Write-Checkpoint 'PILOT-COMPLETE-FINAL-AUDIT-PENDING' $null;Write-PartialManifest 'complete-before-final-audit'
    [pscustomobject]@{passed=$true;pilotRoot=$pilotRoot;pilotManifestSha256=Get-Gate12RLowerSha256 (Join-Path $pilotRoot 'pilot-manifest.json');totalUnityProcessCount=429;measuredBlockCount=384;measuredSampleCount=1152;formalCampaign=$false;gate13rAuthorized=$false}|ConvertTo-Json -Depth 10
    exit 0
}catch{
    $message=$_.Exception.ToString();try{$failure=[ordered]@{schemaVersion=1;receiptKind='gate12r-pilot-failure-receipt-v1';failedAtUtc=[DateTime]::UtcNow.ToString('o');message=$message;completedEntryCount=$script:entries.Count;measuredBlockStarted=@($script:entries|Where-Object role -eq 'measured-non-formal-pilot').Count-gt0;status='FAILED-NO-RESUME-NO-MERGE';formalCampaign=$false;excludedFromFormalAnalysis=$true;automaticResumeAuthorized=$false;partialAttemptMergeAuthorized=$false;gate13rAuthorized=$false};Write-Gate12RAtomicUtf8NoBomJson -Path (Join-Path $pilotRoot 'failure-receipt.json') -Value $failure -Depth 20;Write-Checkpoint 'failed-no-resume-no-merge' $message;Write-PartialManifest 'failed-no-resume-no-merge'}catch{};Write-Error "Gate12R pilot failed closed: $message";exit 1
}
